// GENERERAD av tools/tests/stadier_fixtur.py --skriv — redigera inte för hand.
// PÅHITTADE nätter (METOD M37) och facit ur tools/natt_stadier.py, Python-spegeln av
// NightStages. Raderna är datan: Swift räknar exakt de rader Python räknade. Inget
// kommer från ett riktigt band eller en riktig export.

enum StadierSpegelFixtur {
    /// En natt som K18-poster (`rader`: `bpm,rr…` per sekund från `start`, `-N` hoppar N sekunder;
    /// `lagen`: `sekund,x,y,z` i tusendels g, gäller från sekunden) och spegelns facit.
    struct Natt {
        var namn: String
        var start: Int
        var onset: Int
        var wake: Int
        var rader: String
        var lagen: String
        /// Antal 30 s-epoker.
        var epoker: Int
        /// Behållna slag och skillnader (RRCleaning).
        var slag: Int
        var skillnader: Int
        /// Per epok: `mätt,P(vaken),Q0,Q1,Q2,Q3,stadium,nivå` (stadium och nivå −1 = nil).
        var epokrader: String
        /// De råa särdragen för vissa epoker: `j,` följt av 7 (rörelse) och 12 (hjärta) värden.
        var sardragsrader: String
        /// Minuter per stadium: vaken, lätt, djup, REM.
        var minuter: [Double]
        /// Den förfinade perioden.
        var somnSekunder: Int
        var vakenSekunder: Int
        var glappSekunder: Int
        var vakna: [[Int]]
        var glapp: [[Int]]
        /// [första, sista] Unix-minut, bägge med.
        var somnminuter: [[Int]]
        /// [start, slut, stadium, nivå].
        var spann: [[Int]]
    }

    struct Dfa {
        var namn: String
        var rr: [Double]
        var alfa: Double
    }

